pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IStarlinkSatire_BEP20 {
    function owner() external view returns (address);
    function openTrade() external;
    function tradeEnabled() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x21032D09Cb4F8949883bdEf62D3F1eb5288259BC;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll just get the owner and impersonate them
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner address
        address contractOwner = IStarlinkSatire_BEP20(TARGET).owner();

        // Impersonate the owner to call openTrade()
        vm.prank(contractOwner);
        IStarlinkSatire_BEP20(TARGET).openTrade();

        // Verify tradeEnabled is now true
        bool tradeEnabled = IStarlinkSatire_BEP20(TARGET).tradeEnabled();
        require(tradeEnabled == true, "Trade should be enabled");
        assertEq(tradeEnabled, true, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

